  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult } from './types';
 16→import './App.css';
 17→
 18→function findDuplicateFileNames(files: File[]): string[] {
 19→  const seen = new Set<string>();
 20→  const duplicates = new Set<string>();
 21→  for (const file of files) {
 22→    if (seen.has(file.name)) {
 23→      duplicates.add(file.name);
 24→    }
 25→    seen.add(file.name);
 26→  }
 27→  return Array.from(duplicates);
 28→}
 29→
 30→function AppContent({ tables, refreshTables }: { tables: TableInfo[]; refreshTables: () => Promise<void> }) {
 31→  const { theme, toggleTheme } = useTheme();
 32→  const { language, setLanguage, t } = useTranslation();
 33→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 34→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 35→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 36→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 37→  );
 38→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 39→  const [agentOpen, setAgentOpen] = useState(true);
 40→
 41→  useEffect(() => {
 42→    document.title = t('appTitle');
 43→  }, [t]);
 44→
 45→  useEffect(() => {
 46→    if (tables.length === 0) {
 47→      setQueryResult(null);
 48→      setError(null);
 49→      setEditorQuery(undefined);
 50→    }
 51→  }, [tables]);
 52→
 53→  const errorMessage = error
 54→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 55→    : null;
 56→
 57→  const handleAgentToggle = () => {
 58→    setAgentOpen((prev) => !prev);
 59→  };
 60→
 61→  const handleLoadSample = useCallback(async () => {
 62→    setError(null);
 63→    try {
 64→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 65→      if (!response.ok) throw new Error('Failed to load sample dataset');
 66→      await refreshTables();
 67→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 68→    } catch (e) {
 69→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 70→    }
 71→  }, [refreshTables]);
 72→
 73→  const handleFileUpload = useCallback(
 74→    async (files: File[]) => {
 75→      setError(null);
 76→
 77→      // Check for duplicate filenames within the batch
 78→      const batchDuplicates = findDuplicateFileNames(files);
 79→      if (batchDuplicates.length > 0) {
 80→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
 81→        return;
 82→      }
 83→
 84→      // Check for filenames that match already-uploaded table names
 85→      const existingNames = new Set(tables.map((tbl) => tbl.name));
 86→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
 87→      if (alreadyUploaded.length > 0) {
 88→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
 89→        return;
 90→      }
 91→
 92→      let lastName = '';
 93→      try {
 94→        for (const file of files) {
 95→          const formData = new FormData();
 96→          formData.append('file', file);
 97→          const response = await fetch('/api/upload', {
 98→            method: 'POST',
 99→            body: formData,
100→          });
101→          if (!response.ok) {
102→            const errorData = await response.json();
103→            throw new Error(errorData.detail || 'Failed to upload file');
104→          }
105→          const result = await response.json();
106→          // Handle both single table and array of tables (Excel with multiple sheets)
107→          if (Array.isArray(result)) {
108→            lastName = result[result.length - 1]?.name || '';
109→          } else {
110→            lastName = result.name;
111→          }
112→        }
113→        await refreshTables();
114→        if (lastName) {
115→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
116→        }
117→      } catch (e) {
118→        setError(e instanceof Error ? e.message : 'Failed to upload file');
119→      }
120→    },
121→    [refreshTables]
122→  );
123→
124→  const handleQueryExecute = useCallback(
125→    async (sql: string) => {
126→      setError(null);
127→      setQueryResult(null);
128→      try {
129→        const start = performance.now();
130→        const response = await fetch('/api/query', {
131→          method: 'POST',
132→          headers: { 'Content-Type': 'application/json' },
133→          body: JSON.stringify({ sql }),
134→        });
135→        const elapsed = performance.now() - start;
136→
137→        if (!response.ok) {
138→          const errorData = await response.json();
139→          throw new Error(errorData.detail || 'Query execution failed');
140→        }
141→
142→        const result = await response.json();
143→        setQueryResult({
144→          columns: result.columns,
145→          rows: result.rows,
146→          rowCount: result.rowCount,
147→          executionTimeMs: elapsed,
148→          resultType: result.resultType,
149→        });
150→        await refreshTables();
151→      } catch (e) {
152→        setError(e instanceof Error ? e.message : 'Query execution failed');
153→      }
154→    },
155→    [refreshTables]
156→  );
157→
158→  const handleTableClick = useCallback((tableName: string) => {
159→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
160→  }, []);
161→
162→  const handleTableDelete = useCallback(async (tableName: string) => {
163→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
164→    try {
165→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
166→        method: 'DELETE',
167→      });
168→      if (!response.ok) throw new Error('Failed to delete table');
169→      await refreshTables();
170→    } catch (e) {
171→      setError(e instanceof Error ? e.message : 'Failed to delete table');
172→    }
173→  }, [refreshTables, t]);
174→
175→  const handleDeleteAll = useCallback(async () => {
176→    if (tables.length === 0) return;
177→    if (!confirm(t('deleteAllTablesConfirm'))) return;
178→    try {
179→      for (const table of tables) {
180→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
181→          method: 'DELETE',
182→        });
183→        if (!response.ok) throw new Error('Failed to delete table');
184→      }
185→      await refreshTables();
186→    } catch (e) {
187→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
188→    }
189→  }, [tables, refreshTables, t]);
190→
191→  const appClass = [
192→    'app',
193→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
194→  ].filter(Boolean).join(' ');
195→
196→  const themeIcon = theme === 'dark' ? (
197→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
198→      <circle cx="12" cy="12" r="5" />
199→      <line x1="12" y1="1" x2="12" y2="3" />
200→      <line x1="12" y1="21" x2="12" y2="23" />
201→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
202→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
203→      <line x1="1" y1="12" x2="3" y2="12" />
204→      <line x1="21" y1="12" x2="23" y2="12" />
205→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
206→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
207→    </svg>
208→  ) : (
209→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
210→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
211→    </svg>
212→  );
213→
214→  return (
215→    <div className={appClass}>
216→      <div className="app__sidebar-wrapper">
217→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} onUpload={handleFileUpload} onDeleteAll={handleDeleteAll} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
218→      </div>
219→      {agentOpen ? (
220→        <div className="app__agent-wrapper">
221→          <div className="app__header">
222→            <h1 className="app__title">{t('appTitle')}</h1>
223→            <div className="app__header-actions">
224→              <button
225→                className="app__lang-toggle"
226→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
227→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
228→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
229→              >
230→                {language === 'en' ? 'EN' : '中'}
231→              </button>
232→              <button
233→                className="app__theme-toggle"
234→                onClick={toggleTheme}
235→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
236→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
237→              >
238→                {themeIcon}
239→              </button>
240→              <button
241→                className="app__agent-toggle app__agent-toggle--active"
242→                onClick={handleAgentToggle}
243→              >
244→                {t('editorMode')}
245→              </button>
246→            </div>
247→          </div>
248→          {errorMessage && (
249→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
250→          )}
251→          <AgentPanel
252→            tables={tables}
253→            onUpload={handleFileUpload}
254→            onLoadSample={handleLoadSample}
