 5→export function SessionProvider({ children }: { children: ReactNode }) {
 6→  const sessionIdRef = useRef<string>(crypto.randomUUID());
 7→
 8→  useEffect(() => {
 9→    const sessionId = sessionIdRef.current;
10→
11→    const interval = setInterval(() => {
12→      fetch('/api/heartbeat', {
13→        method: 'POST',
14→        headers: { 'X-Session-ID': sessionId },
15→        keepalive: true,
16→      }).catch(() => {});
17→    }, 30_000);
18→
19→    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
20→      navigator.sendBeacon(`/api/session/cleanup?session_id=${sessionId}`);
21→      e.preventDefault();
22→      e.returnValue = '';
23→    };
24→
25→    window.addEventListener('beforeunload', handleBeforeUnload);
26→
27→    return () => {
28→      clearInterval(interval);
29→      window.removeEventListener('beforeunload', handleBeforeUnload);
30→    };
31→  }, []);
32→
33→  return (
34→    <SessionContext.Provider value={sessionIdRef.current}>
35→      {children}
36→    </SessionContext.Provider>
37→  );
38→}
